        <p class="entry-text">→ <span class="greek">ἐξ-</span>, <span class="greek">ἐπ-</span>, <span class="greek">κατ-</span>, <span class="greek">παρ-</span>, <span class="greek">συν-</span>, <span class="greek">συνεπ-</span>.</p>
